 Vector3 groundLook(){return expedition.Focus+ShipForward*20;}
 string SurfaceJSON(Dictionary<string,bool> checks){var s="{";foreach(var kv in checks)s+="\""+kv.Key+"\":"+kv.Value.ToString().ToLower()+",";return s.TrimEnd(',')+"}";}
 IEnumerator SurfaceChecks(){yield return new WaitForSeconds(1);StageSurface();var checks=new Dictionary<string,bool>();checks["landed_disembark_starts_contract"]=GroundActive&&surface.Current.sites.Count==6;var state=surface.Current;var target=surface.Objective;surface.Interact(true,3);checks["remote_interaction_cannot_complete"]=!state.recorder;checks["mission_dependencies_locked"]=!state.relay&&!state.bossSpawned;
