  surface.Interact(true,.4f);checks["hold_requires_full_duration"]=!state.recorder;surface.Interact(false,.1f);checks["releasing_cancels_hold"]=surface.HoldProgress==0;surface.Interact(true,2);checks["recorder_grants_reward"]=state.recorder&&score==250&&salvageCount==2;long reward=score;surface.Interact(true,4);checks["completed_site_never_rewards_twice"]=score==reward;
  for(int j=0;j<3;j++){target=surface.Objective;for(int i=0;i<2000&&Vector3.Distance(expedition.Focus,surface.World(target))>2.8f;i++){expedition.ScriptWalk(Vector3.ProjectOnPlane(surface.World(target)-expedition.Focus,surface.Up(expedition.Focus)).normalized);expedition.Status(player);expedition.FootStep(.01f);}expedition.ScriptWalk(Vector3.zero);surface.Interact(true,2.1f);}checks["three_distinct_scans_unlock_relay"]=state.scans==3&&surface.Objective.kind=="RELAY";
  target=surface.Objective;for(int i=0;i<2000&&Vector3.Distance(expedition.Focus,surface.World(target))>2.8f;i++){expedition.ScriptWalk(surface.World(target)-expedition.Focus);expedition.Status(player);expedition.FootStep(.01f);}expedition.ScriptWalk(Vector3.zero);surface.Interact(true,2);checks["relay_hold_starts_defense"]=state.defending;
