  surface.Step(.01f);checks["relay_wave_spawns_native_creatures"]=surface.LiveCount>=4&&surface.NativeSteps>0;
  // Weapon collision checks use real geometry and a controlled native foe fixture.
  var foe=surface.Spawn(0,expedition.Focus+ShipForward*8);Vector3 fp=surface.World(foe)+surface.Up(surface.World(foe))*.12f;float hp=foe.hp;surface.Tick(.2f,true);surface.Shoot(expedition.Focus+surface.Up(expedition.Focus)*.5f,(fp-expedition.Focus-surface.Up(expedition.Focus)*.5f).normalized);checks["carbine_consumes_ammo_and_hits_creature"]=surface.Ammo<24&&foe.hp<hp;
  checks["terrain_occludes_gunfire"]=surface.RayLimit(expedition.Focus,-surface.Up(expedition.Focus),30)<3;
  surface.Reload();surface.Tick(1.5f,true);checks["reload_refills_after_delay"]=surface.Ammo==24&&surface.ReloadTime==0;
  surface.Pulse();checks["shockwave_has_cooldown"]=surface.PulseCooldown==8;int kills=state.kills;surface.Damage(foe,1000);long scored=score;surface.Damage(foe,1000);checks["creature_death_rewards_once"]=foe.dead&&score==scored&&state.kills<=kills+1;
  float before=health;invulnerable=0;GroundDamage(12);checks["alien_damage_reduces_health"]=health==before-12;
  // Complete the defense using its ordinary timer while clearing the finite waves.
  for(int i=0;i<2500&&!state.relay;i++){foreach(var f in state.foes)if(!f.dead)surface.Damage(f,1000);surface.Step(.01f);}checks["twenty_four_seconds_completes_relay"]=state.relay&&state.wave==3&&state.sites[4].done;
  target=state.sites[5];for(int i=0;i<4000&&Vector3.Distance(expedition.Focus,surface.World(target))>2.8f;i++){expedition.ScriptWalk(surface.World(target)-expedition.Focus);expedition.Status(player);expedition.FootStep(.01f);surface.Step(.01f);}expedition.ScriptWalk(Vector3.zero);checks["approach_spawns_guardian_after_relay"]=state.bossSpawned;bool boss=false;foreach(var f in state.foes)if(f.kind==2){boss=true;surface.Damage(f,1000);}surface.Interact(true,2);checks["guardian_defeat_unlocks_core"]=boss&&state.core;
  float hpBeforeAttack=health;invulnerable=0;var attacker=surface.Spawn(0,expedition.Focus+PlanetExpedition.SurfaceTangent(surface.Up(expedition.Focus),ShipForward)*1.6f);attacker.cooldown=0;for(int i=0;i<100&&health==hpBeforeAttack;i++)PhysicsTick(.01f);checks["native_alien_windup_deals_real_contact_damage"]=health<hpBeforeAttack;surface.Damage(attacker,1000);
  var miss=surface.Spawn(0,expedition.Focus+PlanetExpedition.SurfaceTangent(surface.Up(expedition.Focus),ShipForward)*1.8f);miss.attacking=true;miss.windup=.01f;miss.local+=PlanetExpedition.SurfaceTangent(surface.Up(expedition.Focus),ShipForward)*12;invulnerable=0;GroundHeal(100);hpBeforeAttack=health;PhysicsTick(.02f);checks["moving_outside_telegraph_avoids_attack"]=health==hpBeforeAttack;surface.Damage(miss,1000);
  for(int i=0;i<600;i++)surface.Step(.01f);checks["dead_creature_records_are_released"]=state.foes.Count==0;
  Vector3 relative=surface.World(state.sites[0])-expedition.Focus;FloatingOrigin();checks["origin_preserves_mission_sites"]=(surface.World(state.sites[0])-expedition.Focus-relative).magnitude<.02f;
  for(int i=0;i<5000&&Vector3.Distance(expedition.Focus,Pos(player))>3;i++){expedition.ScriptWalk(Pos(player)-expedition.Focus);expedition.Status(player);expedition.FootStep(.01f);}expedition.ScriptWalk(Vector3.zero);long pre=score;GroundBoard();checks["boarding_extracts_completed_contract"]=!expedition.OnFoot&&state.extracted&&score==pre+1000;pre=score;GroundBoard();checks["revisit_preserves_contract_and_creature_state"]=surface.Current==state&&state.core&&state.extracted;checks["cleared_patrols_do_not_respawn_on_revisit"]=surface.LiveCount==0;GroundBoard();checks["extraction_bonus_only_once"]=score==pre;checks["enemy_budget_bounded"]=state.foes.Count<=10;ResetRound();checks["new_run_resets_surface_contracts"]=surface.records.Count==0&&!expedition.OnFoot;
  string json=SurfaceJSON(checks);System.IO.File.WriteAllText(System.IO.Path.Combine(EvidenceDir(),"surface-runtime-checks.json"),json);Debug.Log("SURFACE_QA "+json);yield return new WaitForSeconds(.3f);Application.Quit();}
 IEnumerator SurfaceRecord(){yield return new WaitForSeconds(1);StageSurface();quality=2;ApplyQuality();surfaceRecording=true;surface.Scripted=true;paused=false;Cursor.visible=false;string folder=System.IO.Path.Combine(EvidenceDir(),"surface-frames");System.IO.Directory.CreateDirectory(folder);int frame=0;float elapsed=0;bool extracted=false;Vector3 start=expedition.Focus;int maxFoes=0;float minHealth=health;var record=surface.Current;var checks=new Dictionary<string,bool>();
  while(frame<2300&&outcome==""&&!extracted){float dt=1f/12;elapsed+=dt;surface.Sync();var objective=surface.Objective;Vector3 goal=objective==null?Pos(player):surface.World(objective);Vector3 up=surface.Up(expedition.Focus);float distance=Vector3.Distance(expedition.Focus,goal);Vector3 move=Vector3.ProjectOnPlane(goal-expedition.Focus,up).normalized;SurfaceOperations.Foe nearest=null;float near=55;foreach(var f in record.foes)if(!f.dead){float d=Vector3.Distance(surface.World(f),expedition.Focus);if(d<near){near=d;nearest=f;}}
   bool fight=nearest!=null&&(near<20||record.defending);if(fight){Vector3 enemy=surface.World(nearest)+up*(nearest.kind==2?1.3f:.12f);surface.ScriptAim=enemy;expedition.SetAim(enemy);surface.ScriptFire=true;if(surface.Ammo==0)surface.Reload();if(near<8&&surface.PulseCooldown<=0)surface.Pulse();if(near<5)move=Vector3.ProjectOnPlane(expedition.Focus-surface.World(nearest),up).normalized;else move=Vector3.zero;}else{surface.ScriptFire=false;surface.ScriptAim=goal+up;expedition.SetAim(goal+up);if(distance<2.8f)move=Vector3.zero;}
   if(record.defending&&Vector3.Distance(expedition.Focus,surface.World(record.sites[4]))<9&&!fight)move=Vector3.zero;expedition.ScriptWalk(move);expedition.Sprinting=!fight&&distance>6;surface.ScriptInteract=distance<4&&!fight;maxFoes=Mathf.Max(maxFoes,surface.LiveCount);minHealth=Mathf.Min(minHealth,health);
   if(objective==null&&distance<5){GroundBoard();extracted=!expedition.OnFoot;}
   yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(System.IO.Path.Combine(folder,frame.ToString("D4")+".png"));if(frame%120==0)Debug.Log("SURFACE_RECORD "+frame+" recorder="+record.recorder+" scans="+record.scans+" relay="+record.relay+" core="+record.core+" hp="+health+" distance="+distance);frame++;yield return new WaitForSecondsRealtime(dt);
  }
  checks["recorder_recovered"]=record.recorder;checks["three_specimens_scanned"]=record.scans==3;checks["relay_defended"]=record.relay;checks["warden_defeated_and_core_recovered"]=record.core;checks["returned_and_extracted"]=extracted&&record.extracted;checks["damage_enabled"]=true;checks["native_creature_motion"]=surface.NativeSteps>100;checks["carbine_fired"]=surface.ShotsFired>0;System.IO.File.WriteAllText(System.IO.Path.Combine(EvidenceDir(),"surface-loop-checks.json"),SurfaceJSON(checks));Debug.Log("SURFACE_RECORD_FINAL frames="+frame+" kills="+record.kills+" shots="+surface.ShotsFired+" minHealth="+minHealth+" maxFoes="+maxFoes+" score="+score+" outcome="+outcome);yield return new WaitForSeconds(.5f);Application.Quit();}
